package com.travelbird.ai.client;
import com.travelbird.common.enums.*;
import static org.assertj.core.api.Assertions.*;import static org.springframework.test.web.client.match.MockRestRequestMatchers.*;import static org.springframework.test.web.client.response.MockRestResponseCreators.*;import com.travelbird.ai.dto.internal.*;import com.travelbird.ai.entity.AiRequestType;import com.travelbird.global.error.ErrorCode;import com.travelbird.trip.entity.*;import java.time.LocalDate;import java.util.List;import org.junit.jupiter.params.ParameterizedTest;import org.junit.jupiter.params.provider.CsvSource;import org.springframework.http.*;import org.springframework.test.web.client.MockRestServiceServer;import org.springframework.web.client.RestClient;
class AiRecommendationClientErrorContractTest{
 @ParameterizedTest @CsvSource({"422,PLACE_NOT_FOUND","422,PLACE_REGION_MISMATCH","422,CONFLICTING_PLACE_POLICY","400,INVALID_REQUEST","401,INVALID_INTERNAL_AI_KEY","409,AI_JOB_ID_CONFLICT"})void preservesContractErrorCode(int status,ErrorCode code){var builder=RestClient.builder().baseUrl("http://ai.test");var server=MockRestServiceServer.bindTo(builder).build();var client=new HttpAiRecommendationClient(builder.build(),"secret");server.expect(requestTo("http://ai.test/internal/v1/recommendations")).andExpect(header("X-Internal-AI-Key","secret")).andRespond(withStatus(HttpStatus.valueOf(status)).contentType(MediaType.APPLICATION_JSON).body("{\"code\":\""+code.name()+"\",\"message\":\"x\",\"timestamp\":\"2026-09-10T00:00:00Z\"}"));assertThatThrownBy(()->client.recommend(request())).isInstanceOf(AiClientException.class).extracting(e->((AiClientException)e).errorCode()).isEqualTo(code);}
 private RecommendationJobRequest request(){return new RecommendationJobRequest(7L,AiRequestType.GENERAL,"11110",LocalDate.of(2026,10,1),LocalDate.of(2026,10,2),CompanionType.SOLO,List.of(TravelTheme.FOOD),Pace.NORMAL,List.of(),List.of(),List.of(),true);}
}

